def get_arp_name(arp_no):
    entry = ARPEGGIOS.get(arp_no)
    return entry[0] if entry else f'Unknown({arp_no})'


def get_arpeggio(arp_no):
    entry = ARPEGGIOS.get(arp_no)
    if entry is None: return None
    return {'name': entry[0], 'main_cat': entry[1], 'sub_cat': entry[2]}


def get_main_categories():
    return sorted(set(v[1] for v in ARPEGGIOS.values()))


def arps_by_category(main_cat=None, sub_cat=None):
    result = []
    for k, (name, mc, sc) in ARPEGGIOS.items():
        if main_cat and mc != main_cat: continue
        if sub_cat and sc != sub_cat: continue
        result.append((k, name))
    return sorted(result)


if __name__ == '__main__':
    print(f"Total arpeggios: {len(ARPEGGIOS)}")
    print(f"Main categories: {get_main_categories()[:10]}")
